from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class Parameter(SchemaObject):
    name = SchemaField(name="name")
    full_name = SchemaField(name="full_name")
    state = SchemaField(name="state")
    value = SchemaField(name="value")

    def __init__(self, name, full_name, state, value):
        self.name = name
        self.full_name = full_name
        self.state = state
        self.value = value

        super(Parameter, self).__init__()


class ParameterContainer(SchemaObject):
    parameter_type = SchemaField(name="parameter_type")
    simple_parameter = SchemaField(name="simple_parameter", klass=Parameter)
    simple_list_parameter = SchemaField(name="simple_list_parameter", klass=Parameter)
    complex_parameter = SchemaField(name="complex_parameter", klass=Parameter)

    def __init__(self, parameter_type, simple_parameter, simple_list_parameter, complex_parameter):
        self.parameter_type = parameter_type
        self.simple_parameter = simple_parameter
        self.simple_list_parameter = simple_list_parameter
        self.complex_parameter = complex_parameter

        super(ParameterContainer, self).__init__()


class MatchedParameter(SchemaObject):
    mo_uuid = SchemaField(name="mo_uuid", not_null=True)
    nidd_id = SchemaField(name="nidd_id", not_null=True)
    distname = SchemaField(name="distname", not_null=True)
    parameter_name = SchemaField(name="parameter_name", not_null=True)
    state = SchemaField(name="state", not_null=True)
    parameter = SchemaField(name="parameter", klass=ParameterContainer)

    def __init__(self, mo_uuid, nidd_id, distname, parameter_name, state, parameter):
        self.mo_uuid = mo_uuid
        self.nidd_id = nidd_id
        self.distname = distname
        self.parameter_name = parameter_name
        self.state = state
        self.parameter = parameter

        super(MatchedParameter, self).__init__()


class SearchParametersASMV1(SchemaObject):
    total = SchemaField(name="total", not_null=True)
    items = SchemaField(name="items", not_null=True, klass=MatchedParameter, many=True)

    def __init__(self, total, items):
        self.total = total
        self.items = items

        super(SearchParametersASMV1, self).__init__()
